<template>
<div class="overviewPage">
  <div ref="canvasRef" class="canvas" @pointerdown="startCanvasPan" @dblclick="createChapterAt" @contextmenu.prevent="openCanvasMenu" @wheel.prevent="zoomCanvas">
    <p v-if="!nodes.length" class="emptyHint">右键画布创建节点</p>
    <div class="scene" :style="sceneStyle">
      <svg class="connections" viewBox="0 0 4000 2400" preserveAspectRatio="none">
        <line v-for="connection in visibleConnections" :key="connection.__key" :x1="connectionPoint(connection.from).x" :y1="connectionPoint(connection.from).y" :x2="connectionPoint(connection.to).x" :y2="connectionPoint(connection.to).y" @contextmenu.stop.prevent="openConnectionMenu($event, connection)" />
        <line v-if="relationDrag" class="preview" :x1="connectionPoint(relationDrag.from.__key).x" :y1="connectionPoint(relationDrag.from.__key).y" :x2="relationDrag.point.x" :y2="relationDrag.point.y" />
      </svg>
      <section v-for="chapter in nowProjectOverview.chapters" :key="chapter.__key" class="node chapter" :class="{ expanded: chapter.expanded, taskOpen: chapterHasOpenTask(chapter) }" :style="nodeStyle(chapter)" :data-overview-node-key="chapter.__key" @pointerdown.stop="handleNodePointerDown($event, chapter)" @dblclick.stop="startEditing(chapter)" @contextmenu.stop.prevent="chapterMenu(chapter, $event)">
        <div class="chapterMeta">
          <NodeHeader :node="chapter" :editing="editingNodeKey === chapter.__key" :expanded="chapter.expanded" @edit="startEditing(chapter)" @toggle="chapter.expanded = !chapter.expanded" @tasks="toggleTasks(chapter.__key)" />
          <NodeDescription :node="chapter" :editing="editingNodeKey === chapter.__key" />
          <OverviewTaskPanel v-if="taskOpenKey === chapter.__key" :node="chapter" @close="taskOpenKey = null" />
        </div>
        <div v-if="chapter.expanded" class="chapterBoard" @pointerdown.stop="startChapterBoardPan($event, chapter)" @dblclick.stop="createChapterArticleAt($event, chapter)" @contextmenu.stop.prevent="openChapterBoardMenu($event, chapter)" @wheel.stop.prevent="zoomChapterBoard($event, chapter)">
          <article v-for="node in articlesFor(chapter.__key)" :key="node.__key" class="node article childArticle" :class="{ taskOpen: taskOpenKey === node.__key }" :style="childStyle(node)" :data-overview-node-key="node.__key" @pointerdown.stop="handleNodePointerDown($event, node)" @dblclick.stop="startEditing(node)" @contextmenu.stop.prevent="articleMenu(node, $event)">
            <NodeHeader :node="node" :editing="editingNodeKey === node.__key" @edit="startEditing(node)" @tasks="toggleTasks(node.__key)" />
            <NodeDescription :node="node" :editing="editingNodeKey === node.__key" />
            <OverviewTaskPanel v-if="taskOpenKey === node.__key" :node="node" @close="taskOpenKey = null" />
          </article>
        </div>
      </section>
      <article v-for="node in rootArticles" :key="node.__key" class="node article rootArticle" :class="{ taskOpen: taskOpenKey === node.__key }" :style="nodeStyle(node)" :data-overview-node-key="node.__key" @pointerdown.stop="handleNodePointerDown($event, node)" @dblclick.stop="startEditing(node)" @contextmenu.stop.prevent="articleMenu(node, $event)">
        <NodeHeader :node="node" :editing="editingNodeKey === node.__key" @edit="startEditing(node)" @tasks="toggleTasks(node.__key)" />
        <NodeDescription :node="node" :editing="editingNodeKey === node.__key" />
        <OverviewTaskPanel v-if="taskOpenKey === node.__key" :node="node" @close="taskOpenKey = null" />
      </article>
    </div>
  </div>
</div>
</template>
<script setup lang="ts">
import { computed, defineComponent, h, nextTick, onBeforeUnmount, onMounted, ref } from "vue"
import Button from "@/components/global/button.vue"
import DownLineInput from "@/components/other/input/downLineInput.vue"
import MultiLineInput from "@/components/other/textArea/MultiLineInput.vue"
import { showControlPanel } from "@/hooks/controlPanel"
import { useFreeCanvas } from "@/hooks/inputSupport/useFreeCanvas"
import { focusOnArticle, focusOnChapter } from "@/hooks/all-articles/allArticles"
import OverviewTaskPanel from "./OverviewTaskPanel.vue"
import { createOverviewArticle, createOverviewChapter, createOverviewConnection, createTargetArticle, createTargetChapter, getOverviewArticleTarget, getOverviewChapterTarget, isOverviewArticleNode, nowProjectOverview, syncOverviewNodeTitle, type OverviewArticleNode, type OverviewChapterNode, type OverviewConnection } from "./projectOverview"

type Node = OverviewChapterNode | OverviewArticleNode
const NodeHeader = defineComponent({ props: { node: { type: Object, required: true }, editing: Boolean, expanded: Boolean }, emits: ["edit", "toggle", "tasks"], setup(props, { emit }) { return () => h("div", { class: "nodeTitle" }, [props.editing ? h(DownLineInput, { modelValue: (props.node as Node).title, "onUpdate:modelValue": (value: string) => (props.node as Node).title = value, onBlur: () => syncOverviewNodeTitle(props.node as Node), style: { fontWeight: "700" } }) : h("span", { onDblclick: () => emit("edit") }, (props.node as Node).title || (isOverviewArticleNode(props.node as Node) ? "未命名文章" : "未命名章节")), h("div", { class: "nodeTitleActions", style: { display: "flex", flexDirection: "row", flexWrap: "nowrap", gap: "4px" } }, [!isOverviewArticleNode(props.node as Node) ? h(Button, { icon: props.expanded ? "collapse" : "expand", name: props.expanded ? "收起章节" : "展开章节", style: { width: "32px", height: "32px" }, onClick: () => emit("toggle") }) : null, h(Button, { icon: "missionList", name: "管理任务", style: { width: "32px", height: "32px" }, onClick: () => emit("tasks") })])]) } })
const NodeDescription = defineComponent({ props: { node: { type: Object, required: true }, editing: Boolean }, setup(props) { return () => props.editing ? h(MultiLineInput, { class: "nodeDescription", modelValue: (props.node as Node).description, "onUpdate:modelValue": (value: string) => (props.node as Node).description = value, placeholder: isOverviewArticleNode(props.node as Node) ? "文章概述" : "章节介绍" }) : h("div", { class: "nodeDescription" }, (props.node as Node).description || (isOverviewArticleNode(props.node as Node) ? "无概述" : "无介绍")) } })
const canvasRef = ref<HTMLElement>()
const freeCanvas = useFreeCanvas(canvasRef, () => nowProjectOverview.viewport)
const editingNodeKey = ref<string | null>(null), taskOpenKey = ref<string | null>(null)
const nodes = computed<Node[]>(() => [...nowProjectOverview.chapters, ...nowProjectOverview.articles])
const rootArticles = computed(() => nowProjectOverview.articles.filter(node => node.chapterNodeKey === null))
const chapterHasOpenTask = (chapter: OverviewChapterNode) => taskOpenKey.value === chapter.__key || articlesFor(chapter.__key).some(article => article.__key === taskOpenKey.value)
const visibleKeys = computed(() => new Set(nodes.value.filter(node => !isOverviewArticleNode(node) || node.chapterNodeKey === null || nowProjectOverview.chapters.find(chapter => chapter.__key === node.chapterNodeKey)?.expanded).map(node => node.__key)))
const visibleConnections = computed(() => nowProjectOverview.connections.filter(connection => visibleKeys.value.has(connection.from) && visibleKeys.value.has(connection.to)))
const sceneStyle = computed(() => ({ transform: `translate(${nowProjectOverview.viewport.x}px, ${nowProjectOverview.viewport.y}px) scale(${nowProjectOverview.viewport.scale})` }))
const nodeByKey = (key: string) => nodes.value.find(node => node.__key === key)
const articlesFor = (key: string) => nowProjectOverview.articles.filter(node => node.chapterNodeKey === key)
const nodeStyle = (node: Node) => isOverviewArticleNode(node) ? { transform: `translate(${node.position.x}px, ${node.position.y}px)` } : { transform: `translate(${node.position.x}px, ${node.position.y}px)`, width: node.expanded ? `${Math.max(680, node.size.width)}px` : undefined, height: node.expanded ? `${Math.max(500, node.size.height)}px` : undefined }
const childStyle = (node: OverviewArticleNode) => { const view = node.chapterNodeKey ? nowProjectOverview.chapters.find(chapter => chapter.__key === node.chapterNodeKey)?.innerViewport : null; return { transform: `translate(${(view?.x ?? 0) + node.position.x * (view?.scale ?? 1)}px, ${(view?.y ?? 0) + node.position.y * (view?.scale ?? 1)}px) scale(${view?.scale ?? 1})` } }
function globalPosition(node: Node){ if(isOverviewArticleNode(node) && node.chapterNodeKey){ const chapter = nowProjectOverview.chapters.find(item => item.__key === node.chapterNodeKey); if(chapter) return { x: chapter.position.x + 10 + chapter.innerViewport.x + node.position.x * chapter.innerViewport.scale, y: chapter.position.y + 182 + chapter.innerViewport.y + node.position.y * chapter.innerViewport.scale } } return node.position }
const connectionPoint = (key: string) => { const node = nodeByKey(key), position = node ? globalPosition(node) : { x: 0, y: 0 }; return { x: position.x + (node && isOverviewArticleNode(node) ? 130 : 155), y: position.y + 90 } }
const relationDrag = ref<{ from: Node, point: { x: number, y: number } } | null>(null)
let relationTimer: ReturnType<typeof setTimeout> | null = null, suppressContextMenu = false
function startEditing(node: Node){ editingNodeKey.value = node.__key }
async function focusNewNode(node: Node){ editingNodeKey.value = node.__key; await nextTick(); document.querySelector<HTMLElement>(`[data-overview-node-key="${node.__key}"] input`)?.focus() }
function createChapterNode(position: { x: number, y: number }){ const node = createOverviewChapter(position); void focusNewNode(node); return node }
function createArticleNode(chapterKey: string | null, position: { x: number, y: number }){ const node = createOverviewArticle(chapterKey, position); void focusNewNode(node); return node }
function toggleTasks(key: string){ taskOpenKey.value = taskOpenKey.value === key ? null : key }
function openChapter(node: OverviewChapterNode){ focusOnChapter(getOverviewChapterTarget(node) ?? createTargetChapter(node), true) }
function openArticle(node: OverviewArticleNode){ focusOnArticle(getOverviewArticleTarget(node) ?? createTargetArticle(node), true) }
function canvasPoint(event: MouseEvent | PointerEvent){ return freeCanvas.canvasPoint(event) }
function createChapterAt(event: MouseEvent){ freeCanvas.createOnDoubleClick(event, createChapterNode) }
function chapterBoardPoint(event: MouseEvent, chapter: OverviewChapterNode){ const point = canvasPoint(event), view = chapter.innerViewport; return { x: Math.max(0, (point.x - chapter.position.x - 10 - view.x) / view.scale), y: Math.max(0, (point.y - chapter.position.y - 182 - view.y) / view.scale) } }
function createChapterArticleAt(event: MouseEvent, chapter: OverviewChapterNode){ createArticleNode(chapter.__key, chapterBoardPoint(event, chapter)) }
function openCanvasMenu(event: MouseEvent){ if(freeCanvas.consumeContextMenuSuppression() || suppressContextMenu){ suppressContextMenu = false; return } const point = canvasPoint(event); showControlPanel({ option: [{ text: "创建章节节点", click: () => createChapterNode(point) }, { text: "创建文章节点", click: () => createArticleNode(null, point) }] }, { x: event.clientX, y: event.clientY }) }
function openChapterBoardMenu(event: MouseEvent, chapter: OverviewChapterNode){ if(freeCanvas.consumeContextMenuSuppression() || suppressContextMenu){ suppressContextMenu = false; return } showControlPanel({ option: [{ text: "创建文章节点", click: () => createArticleNode(chapter.__key, chapterBoardPoint(event, chapter)) }] }, { x: event.clientX, y: event.clientY }) }
function chapterMenu(node: OverviewChapterNode, event: MouseEvent){ showControlPanel({ title: node.title, option: [{ text: node.expanded ? "收起章节" : "展开章节", click: () => node.expanded = !node.expanded }, { text: getOverviewChapterTarget(node) ? "跳转章节" : "创建章节", click: () => openChapter(node) }, { text: "删除节点", danger: true, click: () => deleteNode(node) }] }, { x: event.clientX, y: event.clientY }) }
function articleMenu(node: OverviewArticleNode, event: MouseEvent){ showControlPanel({ title: node.title, option: [{ text: getOverviewArticleTarget(node) ? "跳转文章" : "创建文章", click: () => openArticle(node) }, { text: "删除节点", danger: true, click: () => deleteNode(node) }] }, { x: event.clientX, y: event.clientY }) }
function openConnectionMenu(event: MouseEvent, connection: OverviewConnection){ showControlPanel({ option: [{ text: "删除连线", danger: true, click: () => nowProjectOverview.connections.splice(nowProjectOverview.connections.indexOf(connection), 1) }] }, { x: event.clientX, y: event.clientY }) }
function deleteNode(node: Node){ if(isOverviewArticleNode(node)) nowProjectOverview.articles.splice(nowProjectOverview.articles.indexOf(node), 1); else { articlesFor(node.__key).forEach(article => { article.position.x += node.position.x; article.position.y += node.position.y; article.chapterNodeKey = null }); nowProjectOverview.chapters.splice(nowProjectOverview.chapters.indexOf(node), 1) } nowProjectOverview.connections = nowProjectOverview.connections.filter(connection => connection.from !== node.__key && connection.to !== node.__key) }
function resizeChapterForArticles(chapter: OverviewChapterNode){ const articles = articlesFor(chapter.__key), right = Math.max(0, ...articles.map(article => article.position.x + 280)), bottom = Math.max(0, ...articles.map(article => article.position.y + 237)); chapter.size.width = Math.min(1200, Math.max(680, right + 30)); chapter.size.height = Math.min(760, Math.max(500, bottom + 192)) }
function handleNodePointerDown(event: PointerEvent, node: Node){ if(event.button === 2){ startRelation(event, node); return } if(event.button !== 0 || editingNodeKey.value === node.__key || (event.target as Element).closest(".taskPanel,.button")) return; const start = { x: event.clientX, y: event.clientY, position: { ...node.position } }, scale = isOverviewArticleNode(node) && node.chapterNodeKey ? nowProjectOverview.chapters.find(chapter => chapter.__key === node.chapterNodeKey)?.innerViewport.scale ?? 1 : 1; startDragging(event.pointerId, move => { node.position.x = snap(start.position.x + (move.clientX - start.x) / (nowProjectOverview.viewport.scale * scale)); node.position.y = snap(start.position.y + (move.clientY - start.y) / (nowProjectOverview.viewport.scale * scale)); if(isOverviewArticleNode(node) && node.chapterNodeKey){ node.position.x = Math.max(0, node.position.x); node.position.y = Math.max(0, node.position.y); const chapter = nowProjectOverview.chapters.find(item => item.__key === node.chapterNodeKey); if(chapter) resizeChapterForArticles(chapter) } }) }
function startRelation(event: PointerEvent, node: Node){ relationTimer = setTimeout(() => { relationTimer = null; relationDrag.value = { from: node, point: canvasPoint(event) } }, 250); const move = (item: PointerEvent) => { if(item.pointerId === event.pointerId && relationDrag.value) relationDrag.value.point = canvasPoint(item) }; const end = (item: PointerEvent) => { if(item.pointerId !== event.pointerId) return; document.removeEventListener("pointermove", move); document.removeEventListener("pointerup", end); document.removeEventListener("pointercancel", end); if(relationTimer){ clearTimeout(relationTimer); relationTimer = null } const relation = relationDrag.value; relationDrag.value = null; const key = (item.target as Element | null)?.closest<HTMLElement>("[data-overview-node-key]")?.dataset.overviewNodeKey, target = key ? nodeByKey(key) : undefined; if(relation && target) createOverviewConnection(relation.from, target); suppressContextMenu = true; setTimeout(() => suppressContextMenu = false, 500) }; document.addEventListener("pointermove", move); document.addEventListener("pointerup", end); document.addEventListener("pointercancel", end) }
function startCanvasPan(event: PointerEvent){ freeCanvas.startCanvasPan(event) }
function zoomCanvas(event: WheelEvent){ freeCanvas.zoomCanvas(event) }
function startChapterBoardPan(event: PointerEvent, chapter: OverviewChapterNode){ if(event.button !== 2) return; const start = { x: event.clientX, y: event.clientY, view: { ...chapter.innerViewport } }; let moved = false; event.preventDefault(); startDragging(event.pointerId, move => { moved ||= Math.abs(move.clientX - start.x) > 4 || Math.abs(move.clientY - start.y) > 4; chapter.innerViewport.x = start.view.x + (move.clientX - start.x) / nowProjectOverview.viewport.scale; chapter.innerViewport.y = start.view.y + (move.clientY - start.y) / nowProjectOverview.viewport.scale }, () => { if(!moved) return; suppressContextMenu = true; setTimeout(() => suppressContextMenu = false, 500) }) }
function zoomChapterBoard(event: WheelEvent, chapter: OverviewChapterNode){ const old = chapter.innerViewport.scale, scale = Math.max(.6, Math.min(1.5, old * (event.deltaY > 0 ? .9 : 1.1))), rect = (event.currentTarget as HTMLElement).getBoundingClientRect(), point = { x: (event.clientX - rect.left) / nowProjectOverview.viewport.scale, y: (event.clientY - rect.top) / nowProjectOverview.viewport.scale }, world = { x: (point.x - chapter.innerViewport.x) / old, y: (point.y - chapter.innerViewport.y) / old }; chapter.innerViewport.scale = scale; chapter.innerViewport.x = point.x - world.x * scale; chapter.innerViewport.y = point.y - world.y * scale }
function startDragging(pointerId: number, move: (event: PointerEvent) => void, after?: () => void){ freeCanvas.startPointerDrag(pointerId, move, after) }
function closeEditing(event: PointerEvent){ if(!(event.target instanceof Element) || !event.target.closest("[data-overview-node-key]")) editingNodeKey.value = null }
onMounted(() => document.addEventListener("pointerdown", closeEditing, true))
onBeforeUnmount(() => { freeCanvas.dispose(); if(relationTimer) clearTimeout(relationTimer); document.removeEventListener("pointerdown", closeEditing, true) })
function snap(value: number){ return Math.round(value * 100) / 100 }
</script>
<style scoped lang="scss">
.overviewPage,.canvas{width:100%;height:100%}.canvas{position:relative;overflow:hidden;background:$paperCanvasColor;touch-action:none}.scene{position:absolute;width:4000px;height:2400px;transform-origin:0 0}.connections{position:absolute;inset:0;width:4000px;height:2400px;overflow:visible;pointer-events:none}.connections line{stroke:$canvasConnectionColor;stroke-width:1.5px;pointer-events:stroke;cursor:context-menu;vector-effect:non-scaling-stroke}.connections .preview{stroke:$connectionPreviewColor;stroke-dasharray:5 4;pointer-events:none}.node{position:absolute;box-sizing:border-box;background:$bgColor;box-shadow:$menuShadow}.node.taskOpen{z-index:100}.chapter{z-index:1;width:310px;min-height:190px;padding:10px;border:1px solid $antiBgColor}.chapterBoard{position:absolute;top:150px;right:10px;bottom:10px;left:10px;overflow:hidden;border:1px solid $bgColor70;background:$paperCanvasColor}.chapter.taskOpen .chapterBoard{overflow:visible}.article{z-index:2;width:260px;min-height:165px;padding:8px;border:1px solid $bgColor70;transform-origin:0 0}.childArticle{top:32px;left:0}.nodeTitle{display:flex;min-height:32px;align-items:center;justify-content:space-between;gap:4px;font-weight:600}.nodeTitle>span,.nodeTitle>:deep(.downLineInput){min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nodeTitleActions{display:flex;flex:0 0 auto;flex-direction:row;flex-wrap:nowrap;gap:4px}.nodeTitleActions .button{width:32px;height:32px}.nodeDescription{min-height:52px;margin:8px 0;color:$previewText;white-space:pre-wrap;overflow-wrap:anywhere}.chapter .nodeDescription{box-sizing:border-box;height:80px;min-height:80px;overflow:auto}.chapter :deep(.multiLineInput){padding:6px}.emptyHint{position:absolute;top:50%;left:50%;margin:0;transform:translate(-50%,-50%);color:$previewText;pointer-events:none}@media(max-width:899px){.chapter{width:290px}.article{width:245px}}
</style>
